'use client';

import type React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import Image from 'next/image';
import {
  ArrowUpDown,
  Building,
  Compass,
  FileText,
  Folder,
  Grid3X3,
  Home,
  IdCard,
  Landmark,
  Layers,
  Lock,
  Magnet,
  Rocket,
  TrendingUp,
  UserCircle,
  Users,
} from 'lucide-react';

import infrafund from '@/../public/assets/svg/infrafund.svg';
import { useAuthSession } from '@/components/auth/auth-session-provider';

interface NavigationItem {
  title: string;
  url: string;
  icon: React.ComponentType<{ className?: string }>;
  isDisabled?: boolean;
}

interface AppSidebarProps {
  className?: string;
  navigationItems?: NavigationItem[];
  model?: 'client' | 'full';
}

function getNavigationItems(
  model: 'client' | 'full' = 'client',
  options: { canCreateProject: boolean } = { canCreateProject: false }
) {
  const fullItems: NavigationItem[] = [
    { title: 'Home', url: '/home', icon: Home },
    { title: 'Create Project', url: '/create-project', icon: Rocket },
    { title: 'Tokenization', url: '/tokenization', icon: Layers },
    { title: 'Investment Portal', url: '/investment-portal', icon: Building },
    {
      title: 'My Digital Asset Offering',
      url: '/digital-assets',
      icon: Grid3X3,
      isDisabled: true,
    },
    {
      title: "Investor's Management",
      url: '/investor-management',
      icon: Users,
    },
    {
      title: 'Investment Requests',
      url: '/investment-requests',
      icon: TrendingUp,
      isDisabled: true,
    },
    { title: 'Asset Management', url: '/asset-management', icon: Folder },
    { title: 'Explore Projects', url: '/explore-projects', icon: Compass },
    { title: 'Swap', url: '/swap', icon: ArrowUpDown },
    { title: 'KYC', url: '/kyc', icon: FileText },
    { title: 'Account', url: '/account', icon: UserCircle },
  ];

  const clientItems: NavigationItem[] = [
    { title: 'Home', url: '/home', icon: Home },
    { title: 'Explore Projects', url: '/explore-projects', icon: Magnet },
    { title: 'KYC', url: '/kyc', icon: IdCard },
    { title: 'Swap', url: '/swap', icon: ArrowUpDown, isDisabled: true },
    {
      title: 'Create Project',
      url: '/create-project',
      icon: Rocket,
      isDisabled: !options.canCreateProject,
    },
    {
      title: 'Tokenization',
      url: '/tokenization',
      icon: Layers,
      isDisabled: true,
    },
    {
      title: 'Investment Portal',
      url: '/investment-portal',
      icon: Landmark,
      isDisabled: true,
    },
    { title: 'Account', url: '/account', icon: UserCircle },
  ];

  return model === 'client' ? clientItems : fullItems;
}

function Navigation({ items }: { items: NavigationItem[] }) {
  const pathname = usePathname();

  const handleItemClick = (item: NavigationItem, e: React.MouseEvent) => {
    if (item.isDisabled) {
      e.preventDefault();
    }
  };

  return (
    <nav className="space-y-2">
      {items.map((item) => {
        const IconComponent = item.icon;
        const isActive = pathname === item.url;

        return (
          <div key={item.url} className="relative chakra-petch">
            <Link
              href={item.isDisabled ? '#' : item.url}
              onClick={(e) => handleItemClick(item, e)}
              aria-disabled={item.isDisabled}
              tabIndex={item.isDisabled ? -1 : 0}
              className={`
                w-full h-12 px-4 rounded-lg transition-all duration-200 ease-in-out
                flex items-center gap-3 group relative
                ${
                  item.isDisabled
                    ? 'text-gray-600 cursor-not-allowed opacity-60'
                    : isActive
                      ? 'bg-card-selected-bg text-primary'
                      : 'text-gray-400 hover:text-gray-200 hover:bg-slate-800/50'
                }
              `}
            >
              <IconComponent className="w-5 h-5 flex-shrink-0" />
              <span className="text-sm font-medium truncate">{item.title}</span>
              {item.isDisabled && <Lock className="w-5 h-5 text-yellow-500" />}
            </Link>
          </div>
        );
      })}
    </nav>
  );
}

export default function AppSidebar({
  className = '',
  model = 'client',
}: AppSidebarProps) {
  const { backendUser } = useAuthSession();
  const navigationItems = getNavigationItems(model, {
    canCreateProject: backendUser?.role === 'project_owner',
  });

  return (
    <div
      className={`h-[928px] bg-card-bg border-card-bg-border text-white w-[261px] flex flex-col rounded-[40px] py-8 ${className}`}
    >
      <div className="w-full h-fit flex justify-start items-center px-7">
        <Image
          src={infrafund}
          width={172}
          height={42}
          alt="InfraFund Logo"
          priority
        />
      </div>

      <div className="px-4 py-6 flex-1 overflow-y-auto">
        <Navigation items={navigationItems} />
      </div>
    </div>
  );
}

'use client';
import type React from 'react';
import AppSidebar from './sidebar';
import Header from './header';
import { usePathname, useRouter } from 'next/navigation';
import { X } from 'lucide-react';
import { useEffect, useState } from 'react';
import { AuthLoadingState } from './auth/auth-state';
import { useAuthSession } from './auth/auth-session-provider';
import { AuthProgressModal } from './auth/auth-progress-modal';
import { BuildInfo } from './build-info';

interface MainLayoutProps {
  children: React.ReactNode;
}

export function MainLayout({ children }: MainLayoutProps) {
  const pathname = usePathname();
  const router = useRouter();
  const isPublicRoute = pathname === '/' || pathname === '/login';
  const { status, isOpenfortLoading } = useAuthSession();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    if (isOpenfortLoading || !pathname) {
      return;
    }

    if (isPublicRoute) {
      if (status === 'authenticated') {
        router.replace('/home');
      }

      return;
    }

    if (status === 'unauthenticated') {
      router.replace('/');
    }
  }, [isOpenfortLoading, isPublicRoute, pathname, router, status]);

  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [pathname]);

  useEffect(() => {
    if (!isMobileMenuOpen) {
      return;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsMobileMenuOpen(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isMobileMenuOpen]);

  const isAwaitingOnboarding = status === 'needs_onboarding';
  // Pre-click SDK init only. Everything else (loading, creating_wallet, error)
  // is now owned by AuthProgressModal so the user sees one consistent surface.
  const showInitialSdkLoading = isOpenfortLoading;
  // Hide route content while bootstrap is in flight or has failed. The
  // progress modal sits on top, but the underlying page would otherwise
  // flash through (especially the dashboard on private routes, since
  // router.replace('/') is async).
  const isBootstrapping =
    status === 'idle' ||
    status === 'loading' ||
    status === 'creating_wallet' ||
    status === 'error';
  // Cover the brief window between page mount on `/?openfortAuthProviderUI=…`
  // and the AuthSessionProvider bootstrap useEffect running. Without this the
  // public landing flashes for a few hundred ms after Google redirects back.
  // Read the URL synchronously to avoid the flash on first render.
  const isHandlingOAuthCallback =
    typeof window !== 'undefined' &&
    window.location.search.includes('openfortAuthProviderUI');

  return (
    <div className="relative min-h-screen overflow-hidden bg-[#0C0C0D]">
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute -top-32 -right-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
        <div className="absolute -bottom-44 -left-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
      </div>

      {isPublicRoute ? (
        <div className="relative z-[999] flex items-center justify-center min-h-screen p-4">
          {showInitialSdkLoading ? (
            <AuthLoadingState message="Loading…" />
          ) : isAwaitingOnboarding ||
            isBootstrapping ||
            isHandlingOAuthCallback ? null : (
            children
          )}
        </div>
      ) : (
        <div className="relative z-[999] flex min-h-screen items-center justify-center p-4 md:p-8 lg:p-12">
          {showInitialSdkLoading ||
          isBootstrapping ||
          isHandlingOAuthCallback ? (
            <AuthLoadingState message="Loading…" />
          ) : (
            <div className="relative z-[999] flex min-h-screen w-full gap-4 p-4 md:gap-8 md:p-8 lg:gap-12 lg:p-12">
              <div className="hidden h-full -mt-3.5 lg:block">
                <AppSidebar />
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex h-fit flex-col gap-6 px-4 md:px-8 xl:px-12">
                  <Header onMenuClick={() => setIsMobileMenuOpen(true)} />
                  <main className="flex-1 rounded-lg backdrop-blur-sm">
                    {children}
                  </main>
                  <BuildInfo className="pb-8 text-center" />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {isMobileMenuOpen ? (
        <div className="fixed inset-0 z-[1000] lg:hidden">
          <button
            type="button"
            aria-label="Close navigation menu"
            className="absolute inset-0 bg-black/65 backdrop-blur-sm"
            onClick={() => setIsMobileMenuOpen(false)}
          />
          <div className="absolute left-0 top-0 h-full max-w-[82vw]">
            <AppSidebar className="h-full rounded-none rounded-r-[32px]" />
            <button
              type="button"
              aria-label="Close navigation menu"
              onClick={() => setIsMobileMenuOpen(false)}
              className="absolute right-4 top-4 rounded-full border border-white/15 bg-[#0C0C0D]/80 p-2 text-white transition hover:border-primary/50 hover:text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
            >
              <X size={20} />
            </button>
          </div>
        </div>
      ) : null}

      <AuthProgressModal />
    </div>
  );
}

import 'server-only';

import { ApiError } from '@/server/http';
import {
  createProjectDraft,
  findProjectForOwner,
  replaceProjectMilestones,
  submitProject,
  updateProjectInformation,
  upsertProjectCampaign,
  upsertProjectContact,
  type ProjectWithDetails,
} from '@/server/repositories/projects';
import { authenticateAppRequest } from '@/server/services/auth';
import type {
  CampaignInput,
  ContactInput,
  MilestonesInput,
  ProjectInformationInput,
} from '@/server/validation/projects';

async function getAuthenticatedProjectOwnerId(accessToken: string) {
  const { user } = await authenticateAppRequest(accessToken);

  if (user.role !== 'project_owner') {
    throw new ApiError('FORBIDDEN', 'Project owner account required.');
  }

  return user.id;
}

async function assertProjectOwner(projectId: string, accessToken: string) {
  const ownerUserId = await getAuthenticatedProjectOwnerId(accessToken);
  const project = await findProjectForOwner(projectId, ownerUserId);

  if (!project) {
    throw new ApiError('NOT_FOUND', 'Project not found.');
  }

  return project;
}

function serializeDecimal(
  value: { toString: () => string } | null | undefined
) {
  return value?.toString() ?? null;
}

function serializeDate(value: Date | null | undefined) {
  return value?.toISOString() ?? null;
}

function serializeProject(project: ProjectWithDetails) {
  return {
    id: project.id,
    owner_user_id: project.ownerUserId,
    name: project.name,
    description: project.description,
    type: project.type,
    infrastructure_type: project.infrastructureType,
    project_status: project.projectStatus,
    crowdfunding_model: project.crowdfundingModel,
    submission_status: project.submissionStatus,
    current_step: project.currentStep,
    digital_asset_symbol: project.digitalAssetSymbol,
    target_investment_amount: serializeDecimal(project.targetInvestmentAmount),
    target_investment_currency: project.targetInvestmentCurrency,
    raised_before: project.raisedBefore,
    website_url: project.websiteUrl,
    social_url: project.socialUrl,
    submitted_at: serializeDate(project.submittedAt),
    created_at: project.createdAt.toISOString(),
    updated_at: project.updatedAt.toISOString(),
    contact: project.contact
      ? {
          first_name: project.contact.firstName,
          last_name: project.contact.lastName,
          email: project.contact.email,
          title: project.contact.title,
          phone_number: project.contact.phoneNumber,
        }
      : null,
    campaign: project.campaign
      ? {
          token_name: project.campaign.tokenName,
          digital_asset_supply: serializeDecimal(
            project.campaign.digitalAssetSupply
          ),
          price: serializeDecimal(project.campaign.price),
          currency: project.campaign.currency,
          min_raise: serializeDecimal(project.campaign.minRaise),
          max_raise: serializeDecimal(project.campaign.maxRaise),
          min_contribution: serializeDecimal(project.campaign.minContribution),
          max_contribution: serializeDecimal(project.campaign.maxContribution),
          start_date: serializeDate(project.campaign.startDate),
          end_date: serializeDate(project.campaign.endDate),
          general_contractor_wallet_address:
            project.campaign.generalContractorWalletAddress,
          pledge_address: project.campaign.pledgeAddress,
        }
      : null,
    documents: project.documents.map((document) => ({
      id: document.id,
      kind: document.kind,
      file_name: document.fileName,
      mime_type: document.mimeType,
      size_bytes: document.sizeBytes,
      checksum: document.checksum,
      storage_url: document.storageUrl,
    })),
    digital_twin_model: project.digitalTwinModels[0]
      ? {
          id: project.digitalTwinModels[0].id,
          name: project.digitalTwinModels[0].name,
          asset_url: project.digitalTwinModels[0].assetUrl,
          format: project.digitalTwinModels[0].format,
          source: project.digitalTwinModels[0].source,
          components: project.digitalTwinModels[0].components.map(
            (component) => ({
              id: component.id,
              external_id: component.externalId,
              display_name: component.displayName,
              node_name: component.nodeName,
              category: component.category,
              sort_order: component.sortOrder,
              is_visible: component.isVisible,
            })
          ),
        }
      : null,
    milestones: project.milestones.map((milestone) => ({
      id: milestone.id,
      name: milestone.name,
      cost: serializeDecimal(milestone.cost),
      end_date: serializeDate(milestone.endDate),
      sort_order: milestone.sortOrder,
      components: milestone.components.map((mapping) => ({
        id: mapping.component.id,
        external_id: mapping.component.externalId,
        display_name: mapping.component.displayName,
        node_name: mapping.component.nodeName,
        category: mapping.component.category,
        sort_order: mapping.sortOrder,
        is_visible: mapping.component.isVisible,
      })),
    })),
  };
}

export async function createPreSaleProjectDraft(accessToken: string) {
  const ownerUserId = await getAuthenticatedProjectOwnerId(accessToken);
  const project = await createProjectDraft(ownerUserId);

  return serializeProject(project);
}

export async function getProject(accessToken: string, projectId: string) {
  const project = await assertProjectOwner(projectId, accessToken);

  return serializeProject(project);
}

export async function saveProjectContact(
  accessToken: string,
  projectId: string,
  input: ContactInput
) {
  await assertProjectOwner(projectId, accessToken);
  const project = await upsertProjectContact(projectId, input);

  return serializeProject(project);
}

export async function saveProjectInformation(
  accessToken: string,
  projectId: string,
  input: ProjectInformationInput
) {
  await assertProjectOwner(projectId, accessToken);
  const project = await updateProjectInformation(projectId, input);

  return serializeProject(project);
}

export async function saveProjectMilestones(
  accessToken: string,
  projectId: string,
  input: MilestonesInput
) {
  await assertProjectOwner(projectId, accessToken);
  const project = await replaceProjectMilestones(projectId, input);

  return serializeProject(project);
}

export async function saveProjectCampaign(
  accessToken: string,
  projectId: string,
  input: CampaignInput
) {
  await assertProjectOwner(projectId, accessToken);
  const project = await upsertProjectCampaign(projectId, input);

  return serializeProject(project);
}

export async function submitProjectDraft(
  accessToken: string,
  projectId: string
) {
  const existing = await assertProjectOwner(projectId, accessToken);

  if (!existing.contact || !existing.campaign || !existing.name) {
    throw new ApiError(
      'VALIDATION_ERROR',
      'Project draft is incomplete before submission.'
    );
  }

  const project = await submitProject(projectId);

  return serializeProject(project);
}

'use client';

// AuthSessionProvider bridges Openfort identity with our app session.
//
// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
// session (JWT + httpOnly refresh cookie), user profile, and the qualification
// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
// we call create() explicitly at the right moment.
//
// Status machine:
//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
//                 ↘ creating_wallet → authenticated   (existing user)
//                 ↘ error                             (any failure)
//
// New-user path (registration):
//   Openfort auth → check backend (exists: false) → qualification questionnaire
//   → backend exchange with role/type → createWalletIfNeeded → authenticated
//
// Existing-user path (login):
//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
//                                        ↘ no cookie → check backend (exists: true)
//                                          → backend exchange → createWalletIfNeeded
//
// createWalletIfNeeded always calls Openfort's create() to load the iframe and
// establish the embedded-wallet connection. For new users create() provisions
// the wallet; for returning users it reconnects to the existing one. Skipping
// this step for returning users leaves the wallet in [Not connected] state
// because the embedded-wallet iframe is never loaded (connectOnLogin: false).

import type { User } from '@openfort/openfort-js';
import {
  RecoveryMethod,
  useOpenfortCore,
  useUI,
  useUser,
} from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  deleteBackendAccount,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { usePathname } from 'next/navigation';
import { reportError } from '@/lib/error-reporting';

const OPENFORT_CALLBACK_PARAMS = [
  'openfortAuthProviderUI',
  'access_token',
  'user_id',
  'error',
] as const;

function stripOpenfortCallbackParams() {
  if (typeof window === 'undefined') return;
  const url = new URL(window.location.href);
  let mutated = false;
  for (const key of OPENFORT_CALLBACK_PARAMS) {
    if (url.searchParams.has(key)) {
      url.searchParams.delete(key);
      mutated = true;
    }
  }
  if (mutated) {
    window.history.replaceState({}, document.title, url.toString());
  }
}

// Hard-navigate to the public landing page. Using window.location.assign
// (instead of router.replace) forces a full document reload, which is the
// canonical Openfort disconnect pattern (see docs: useSignOut + onSignOutSuccess
// → window.location.href = "/"). Soft navigation leaves OpenfortProvider and
// ConnectModal mounted, so any leftover OAuth callback params or in-memory
// SDK state can re-arm the auth flow before the next mount.
function hardNavigateToRoot() {
  if (typeof window === 'undefined') return;
  stripOpenfortCallbackParams();
  if (window.location.pathname === '/') {
    window.location.reload();
  } else {
    window.location.assign('/');
  }
}

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

type ErrorCategory = 'recoverable' | 'fatal';

type AuthStepId =
  | 'signing_in'
  | 'checking_account'
  | 'restoring_session'
  | 'creating_account'
  | 'loading_profile'
  | 'connecting_wallet'
  | 'setting_up_wallet';

type AuthStepStatus = 'pending' | 'active' | 'done' | 'error';

export interface AuthProgressStep {
  id: AuthStepId;
  label: string;
  status: AuthStepStatus;
  errorMessage?: string;
}

interface AuthProgress {
  steps: AuthProgressStep[];
  isVisible: boolean;
}

const STEP_LABELS: Record<AuthStepId, string> = {
  signing_in: 'Authenticating with Openfort',
  checking_account: 'Checking your account',
  restoring_session: 'Restoring your session',
  creating_account: 'Creating your account',
  loading_profile: 'Loading your profile',
  connecting_wallet: 'Connecting your wallet',
  setting_up_wallet: 'Setting up your wallet',
};

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  errorCategory: ErrorCategory | null;
  retry: () => void;
  refreshSession: () => Promise<string | null>;
  deleteAccount: () => Promise<void>;
  logout: () => Promise<void>;
  authProgress: AuthProgress | null;
  dismissProgress: () => void;
  cancelAuthFlow: () => Promise<void>;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  if (typeof error === 'string' && error) {
    return error;
  }

  if (error && typeof error === 'object') {
    if (
      'message' in error &&
      typeof error.message === 'string' &&
      error.message
    ) {
      return error.message;
    }

    try {
      return JSON.stringify(error);
    } catch {}
  }

  return 'Failed to initialize your session.';
}

function getUserFacingErrorMessage(message: string) {
  if (/failed to establish iFrame connection/i.test(message)) {
    return "We couldn't connect to the wallet service. Please check your connection and try again.";
  }

  if (
    /openfort shield rejected the wallet setup request|failed to create account or device|a_invalid|invalid token/i.test(
      message
    )
  ) {
    return 'Wallet setup is currently misconfigured on the server. Request Admin to check SHIELD env var settings; retrying will not fix it.';
  }

  if (
    /next_public_shield_api_key|shield_secret_key|shield_encryption_share/i.test(
      message
    )
  ) {
    return 'Wallet setup is unavailable because a required Openfort Shield configuration value is missing or invalid. Request Admin to check SHIELD env var settings.';
  }

  if (
    /user type is required|user role is required|organization name is required/i.test(
      message
    )
  ) {
    return `Account setup is missing required onboarding data. ${message}`;
  }

  if (/openfort access token is unavailable/i.test(message)) {
    return 'Your Openfort sign-in session is missing or expired. Please sign in again.';
  }

  if (
    /not logged in|session expired|invalid openfort access token/i.test(message)
  ) {
    return 'Your session expired. Please sign in again.';
  }

  if (/failed to fetch|networkerror/i.test(message)) {
    return 'We hit a network issue. Please try again.';
  }

  if (/internal server error/i.test(message)) {
    return 'Our service is temporarily unavailable. Please try again in a moment.';
  }

  if (message && message !== 'Failed to initialize your session.') {
    return message;
  }

  return 'Something went wrong. Please try again.';
}

function classifyError(message: string): ErrorCategory {
  if (
    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
      message
    )
  ) {
    return 'recoverable';
  }

  return 'fatal';
}

