    project_status: 'ready_to_launch',
    raised_before: false,
    website_url: '',
    social_url: '',
  });
  const [milestones, setMilestones] = useState<MilestoneDraft[]>([
    emptyMilestone(),
  ]);
  const [campaign, setCampaign] = useState<ProjectCampaignPayload>({
    token_name: '',
    digital_asset_supply: '',
    price: '',
    currency: 'USDC',
    min_raise: '',
    max_raise: '',
    min_contribution: '',
    max_contribution: '',
    start_date: '',
    end_date: '',
    general_contractor_wallet_address: '',
